@startuml

class Doctor {
  +practitionerNumber : int
  +fullName : string
  +address : string
  +phoneNumber : string
  +signature : string
}

class Patient {
  +healthNumber : string
  +firstName : string
  +lastName : string
  +dateOfBirth : date
  +address : string
  +phoneNumber : string
}

class Requisition {
  +validFrom : date
  +repetitionNumber : int
  +repetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

class Test {
  +duration : int
}

class TestGroup {
}

class TestResult {
  +isPositive : boolean
  +report : string
}

class Lab {
  +address : string
  +registrationNumber : string
  +startTime : time
  +endTime : time
  +cancellationFee : float
}

class Appointment {
  +confirmationNumber : string
  +date : date
  +startTime : time
  +endTime : time
}

Doctor "1" -- "0..*" Requisition : prescribes
Patient "1" -- "0..*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "0..*" -- "1" TestGroup : belongs to
Test "1" -- "0..*" TestResult : produces
Doctor "1" -- "0..*" TestResult : views
Patient "1" -- "0..*" TestResult : views
Patient "1" -- "0..*" Appointment : books
Appointment "1" -- "1" Lab : at
Appointment "1" -- "1" Test : for
Appointment "1" -- "1" Requisition : for

@enduml

